import React, { useState } from 'react';
import Modal from '../../components/Modal';
import { Button, Loading, ErrorState, EmptyState } from '../../components/ui';
import CategoryForm from '../../components/categories/CategoryForm';
import CategoryCard from '../../components/categories/CategoryCard';
import useCategories from '../../hooks/useCategories';

const CategoriesPage = () => {
  const { categories, loading, error, refetch, saveCategory, deleteCategory, reorderCategories } = useCategories();

  const [showForm, setShowForm] = useState(false);
  const [editingCategory, setEditingCategory] = useState(null);
  const [draggedId, setDraggedId] = useState(null);

  const startCreate = () => {
    setEditingCategory(null);
    setShowForm(true);
  };

  const startEdit = (cat) => {
    setEditingCategory(cat);
    setShowForm(true);
  };

  const handleSave = async (form) => {
    await saveCategory(form, editingCategory);
    setShowForm(false);
  };

  const handleDrop = (targetCategory) => {
    if (draggedId === null || draggedId === targetCategory.id) return;
    reorderCategories(draggedId, targetCategory.id);
    setDraggedId(null);
  };

  if (loading) return <Loading text="Cargando categorías..." />;
  if (error) return <ErrorState title="🗂️ Categorías" message={error} onRetry={refetch} />;

  return (
    <div>
      <div className="flex justify-between items-center mb-2">
        <h1 className="text-slate-200 text-[28px]">🗂️ Categorías</h1>
        <Button onClick={startCreate}>+ Nueva Categoría</Button>
      </div>
      <p className="text-slate-500 text-[13px] mb-5">
        Arrastra las tarjetas para cambiar el orden en que aparecen en el menú.
      </p>

      {showForm && (
        <Modal
          title={editingCategory ? '✏️ Editar Categoría' : 'Nueva Categoría'}
          onClose={() => setShowForm(false)}
          maxWidth={480}
        >
          <CategoryForm category={editingCategory} onSave={handleSave} />
        </Modal>
      )}

      <div className="grid gap-4" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(240px, 1fr))' }}>
        {categories.map((cat) => (
          <CategoryCard
            key={cat.id}
            category={cat}
            isDragging={draggedId === cat.id}
            onDragStart={() => setDraggedId(cat.id)}
            onDrop={() => handleDrop(cat)}
            onEdit={() => startEdit(cat)}
            onDelete={() => deleteCategory(cat)}
          />
        ))}
      </div>

      {categories.length === 0 && <EmptyState message="No hay categorías todavía." className="py-10" />}
    </div>
  );
};

export default CategoriesPage;
